"""Rule-based bot detection over the access log.

Rules (per uid):
  R1 declared-ua   : user-agent string contains 'bot' (case-insensitive)
  R2 request-rate  : more than 150 requests inside any sliding 300 s window
                     (i.e. >30 req/min sustained for 5 minutes)
  R3 low-gap-cv    : coefficient of variation of inter-request gaps < 0.1
                     while the uid has more than 100 requests
  R4 probe-path    : requested a known probe path (e.g. /wp-admin.php)
"""
import json
import statistics
from collections import defaultdict
from datetime import datetime

PROBE_PATHS = {"/wp-admin.php"}

RATE_WINDOW_S = 300.0     # 5 minutes
RATE_MAX_REQS = 150       # strictly more than this => flagged (>30/min)
CV_THRESHOLD = 0.1
CV_MIN_REQUESTS = 100

RULES = ("declared_ua", "request_rate", "gap_cv", "probe_path")


def parse_line(line):
    ts, uid, path, ua = line.rstrip("\n").split("\t", 3)
    return datetime.fromisoformat(ts), uid, path, ua


def load_rows(path="access.log"):
    with open(path) as f:
        return [parse_line(line) for line in f if line.strip()]


def _max_requests_in_window(stamps, window_s, limit):
    """True if any sliding window of window_s seconds holds > limit requests."""
    left = 0
    for right in range(len(stamps)):
        while (stamps[right] - stamps[left]).total_seconds() > window_s:
            left += 1
        if right - left + 1 > limit:
            return True
    return False


def analyze(rows):
    """Return (flags_by_uid, rule_uids).

    flags_by_uid: uid -> set of rule names that fired
    rule_uids:    rule name -> set of uids it fired on
    """
    by_uid = defaultdict(list)
    for _, uid, path, ua in rows:
        by_uid[uid].append((path, ua))

    stamps_by_uid = {}
    for ts, uid, _, _ in rows:
        stamps_by_uid.setdefault(uid, []).append(ts)
    for uid in stamps_by_uid:
        stamps_by_uid[uid].sort()

    flags = {uid: set() for uid in by_uid}
    rule_uids = {r: set() for r in RULES}

    for uid, hits in by_uid.items():
        n = len(hits)

        # R1: declared UA
        if any("bot" in ua.lower() for _, ua in hits):
            flags[uid].add("declared_ua")

        # R2: sustained request rate
        if _max_requests_in_window(stamps_by_uid[uid], RATE_WINDOW_S, RATE_MAX_REQS):
            flags[uid].add("request_rate")

        # R3: robotic regularity (low CV of gaps, enough requests)
        if n > CV_MIN_REQUESTS:
            stamps = stamps_by_uid[uid]
            gaps = [(stamps[k + 1] - stamps[k]).total_seconds()
                    for k in range(n - 1)]
            mean_gap = statistics.fmean(gaps)
            if mean_gap > 0:
                cv = statistics.pstdev(gaps) / mean_gap
                if cv < CV_THRESHOLD:
                    flags[uid].add("gap_cv")

        # R4: known probe paths
        if any(path in PROBE_PATHS for path, _ in hits):
            flags[uid].add("probe_path")

    for uid, rules in flags.items():
        for r in rules:
            rule_uids[r].add(uid)

    return flags, rule_uids


def summarize(rows, flags, rule_uids):
    flagged_uids = sorted(u for u, rs in flags.items() if rs)
    flagged_rows = sum(1 for _, uid, _, _ in rows if uid in set(flagged_uids))
    return {
        "total_rows": len(rows),
        "flagged_rows": flagged_rows,
        "clean_rows": len(rows) - flagged_rows,
        "flagged_uid_count": len(flagged_uids),
        "rule_counts": {r: len(rule_uids[r]) for r in RULES},
        "rule_uids": {r: sorted(rule_uids[r]) for r in RULES},
        "flagged_uids": flagged_uids,
    }
